import pandas as pd

def calculate_yoy_growth(user_transactions: pd.DataFrame) -> pd.DataFrame:
    if user_transactions.empty:
        return pd.DataFrame(columns=['year', 'product_id', 'curr_year_spend', 'prev_year_spend', 'yoy_rate'])

    user_transactions['year'] = pd.to_datetime(user_transactions['transaction_date']).dt.year
    yearly = user_transactions.groupby(['product_id', 'year'])['spend'].sum().reset_index()
    yearly = yearly.rename(columns={'spend': 'curr_year_spend'})
    yearly = yearly.sort_values(by=['product_id', 'year'])

    yearly['prev_year_spend'] = yearly.groupby('product_id')['curr_year_spend'].shift(1)
    yearly['yoy_rate'] = ((yearly['curr_year_spend'] - yearly['prev_year_spend']) * 100.0 / yearly['prev_year_spend']).round(2)

    res = yearly[['year', 'product_id', 'curr_year_spend', 'prev_year_spend', 'yoy_rate']]
    return res.sort_values(by=['product_id', 'year']).reset_index(drop=True)
